package com.yuegang.zhihui.ai.infrastructure;import com.yuegang.zhihui.ai.domain.*;import java.util.*;import org.springframework.web.client.RestClient;public final class DoubaoModelGateway implements ModelGateway{private final RestClient client;private final String model;public DoubaoModelGateway(String base,String key,String model){if(key==null||key.isBlank())throw new IllegalStateException("Doubao key missing");this.model=model;client=RestClient.builder().baseUrl(base).defaultHeader("Authorization","Bearer "+key).build();}public String answer(String system,String user){Map<?,?> body=client.post().uri("/chat/completions").body(Map.of("model",model,"temperature",0.2,"messages",List.of(Map.of("role","system","content",system),Map.of("role","user","content",user)))).retrieve().body(Map.class);if(body==null)throw new IllegalStateException("empty model response");var choices=(List<?>)body.get("choices");if(choices==null||choices.isEmpty())throw new IllegalStateException("model choice missing");var message=(Map<?,?>)((Map<?,?>)choices.getFirst()).get("message");return Objects.toString(message.get("content"),"");}}
